#include <stdio.h>

#define MIN(a,b) ((a)<(b)?(a):(b))
#define MAX(a,b) ((a)>(b)?(a):(b))
#define ARRAY_SIZE(arr) (sizeof(arr)/sizeof(arr[0]))

int main() {
    printf("Min: %d\n", MIN(10, 20));
    printf("Max: %d\n", MAX(10, 20));
    int arr[] = {1, 2, 3, 4, 5};
    printf("Size: %zu\n", ARRAY_SIZE(arr));
    return 0;
}
